pub fn run_job(cwd: &Path, job: &str) -> JsonValue {
    run_json(
        cwd,
        [
            "program",
            "module",
            "foreign-process",
            "benchmark-job",
            "run",
            job,
            "--format",
            "json",
        ],
    )
}

pub fn fetch_result(target: &Path, source: &Path, result: &str, key: &Path) -> JsonValue {
    let address = unused_address();
    let server = spawn_server(target, &address, result, EXECUTOR, key);
    let value = run_json(
        source,
        [
            OsStr::new("program"),
            OsStr::new("module"),
            OsStr::new("foreign-process"),
            OsStr::new("benchmark-job"),
            OsStr::new("fetch-result-chunked"),
            OsStr::new(&address),
            OsStr::new(result),
            OsStr::new("--node-id"),
            OsStr::new("capsule.receiver"),
            OsStr::new("--expect-node"),
            OsStr::new(EXECUTOR),
            OsStr::new("--auth-key"),
            key.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    );
    assert!(server.wait_with_output().unwrap().status.success());
    value
}

pub fn completion_head(cwd: &Path, job: &str) -> PathBuf {
    ObjectStore::open(cwd)
        .objects_dir()
        .parent()
        .unwrap()
        .join("foreign-process")
        .join("benchmark-run-jobs")
        .join("v1")
        .join(format!("{job}.head"))
}

pub fn unused_address() -> String {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    listener.local_addr().unwrap().to_string()
}

pub fn text<'a>(value: &'a JsonValue, field: &str) -> &'a str {
    value[field].as_str().unwrap()
}

